@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#17201d;--muted:#75817b;--paper:#f1f0e9;--panel:#fbfaf5;--line:#dfe1d8;--green:#c7f36b;--green-dark:#315b29;--orange:#f2814b;--blue:#8ebeff;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}*{box-sizing:border-box}body{margin:0;background:#e8e9e1;color:var(--ink);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(#afb7aa 0.6px,transparent .6px);background-size:8px 8px}.shell{max-width:1280px;margin:0 auto;padding:0 40px}.topbar{height:74px;border-bottom:1px solid #d6d9ce;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:10px;align-items:center;color:var(--ink);text-decoration:none;font-weight:700;font-size:19px;letter-spacing:-.8px}.brand-icon{width:30px;height:30px;background:var(--green);display:grid;place-items:center;font-family:var(--mono);font-size:17px;border-radius:4px;box-shadow:3px 3px 0 var(--ink)}.brand-dot{color:#769a3d}.top-status,.help-button,.eyebrow,.stat-label,.stat-foot,.panel-title,.tiny-tag,.outlet-id,.status-pill,.tab,.number,.select-label,.quality-control,.tier-level,.campaign-strip>div:nth-child(2)>b,.run-button,.network-legend,.network-foot,.audience-score,.ledger-total,.ledger-row,.sidebar-bottom,footer,.modal-close,.guide-grid b{font-family:var(--mono);letter-spacing:.04em}.top-status{font-size:10px;color:#68756c}.live-dot{display:inline-block;width:7px;height:7px;background:#67b758;border-radius:50%;margin-right:7px;box-shadow:0 0 0 3px #67b75826}.divider{padding:0 9px;color:#afb5a9}.help-button{border:1px solid #cad0c4;background:transparent;color:var(--ink);height:34px;padding:0 10px;border-radius:3px;font-size:12px;cursor:pointer}.help-button:hover{background:#dce1d4}.help-button span{font-size:10px;margin-left:5px}.game-heading{display:flex;justify-content:space-between;align-items:flex-end;padding:31px 0 26px}.eyebrow{font-size:10px;color:#78837c;margin:0 0 9px}.eyebrow span{color:#93b94f;padding:0 3px}.game-heading h1{font-size:48px;line-height:.91;letter-spacing:-3.5px;margin:0;font-weight:700}.game-heading h1 em{font-style:normal;color:#698e36}.heading-note{display:flex;gap:12px;align-items:center;margin-right:10px;padding-bottom:4px}.heading-note p{font-size:13px;font-weight:600;line-height:1.35;margin:0}.note-mark{width:39px;height:39px;display:grid;place-items:center;border:1px solid #b9c3aa;border-radius:50%;color:#68913c;font-size:23px}.hud{background:var(--ink);color:#f4f3ea;border-radius:5px;display:grid;grid-template-columns:repeat(4,1fr);padding:17px 20px;margin-bottom:15px;box-shadow:0 5px 0 #c9cdc1}.hud-stat{position:relative;padding-left:17px;border-left:1px solid #3b4740;min-height:55px}.hud-stat:first-child{border:0;padding-left:0}.stat-label{font-size:9px;color:#97a39a;display:block;margin-bottom:8px}.hud-stat strong{font-family:var(--mono);font-size:23px;letter-spacing:-1px;font-weight:500;line-height:1}.stat-dim{font-size:12px;color:#819088}.delta,.stat-foot{font-size:9px;color:#a6b29f;display:block;margin-top:8px}.delta{color:#c6f17b}.day-track,.mini-meter{height:3px;width:90px;background:#46504a;margin-top:8px}.day-track i,.mini-meter i{display:block;height:100%;width:3%;background:var(--green);transition:width .3s}.mini-meter{width:100px;margin-top:8px}.workspace{display:grid;grid-template-columns:258px minmax(0,1fr);gap:15px;align-items:stretch}.panel{background:var(--panel);border:1px solid #d9ddd2;border-radius:5px;box-shadow:0 3px 0 #d9dcd2}.sidebar{padding:17px 15px 12px;display:flex;flex-direction:column;min-height:525px}.panel-title{font-size:10px;font-weight:500;display:flex;justify-content:space-between;align-items:center;padding:0 1px 14px;border-bottom:1px solid var(--line)}.tiny-tag{border:1px solid #d7dbd1;color:#859087;padding:2px 5px;font-size:9px;border-radius:2px}.outlet-list{padding:8px 0}.outlet-item{display:flex;justify-content:space-between;align-items:center;padding:11px 9px;border-radius:4px;cursor:pointer;border:1px solid transparent;margin:2px 0;transition:.15s}.outlet-item:hover{background:#f2f4ec}.outlet-item.active{background:#eef4df;border-color:#dbe8c2}.outlet-item-left{display:flex;gap:9px;align-items:center}.outlet-icon{width:29px;height:29px;border-radius:3px;background:#e8eee1;color:#52753d;display:grid;place-items:center;font-size:14px}.outlet-item.active .outlet-icon{background:var(--green)}.outlet-item b{font-size:12px;display:block}.outlet-item small{font-family:var(--mono);font-size:9px;color:#7e8980;display:block;margin-top:3px}.outlet-item .outlet-cash{font-family:var(--mono);font-size:10px;color:#657369}.expand-button{margin-top:auto;border:1px dashed #b5c29e;color:#405b34;background:#f6f9ee;border-radius:4px;padding:12px 9px;display:flex;align-items:center;gap:9px;text-align:left;cursor:pointer}.expand-button:hover{background:#eef6df;border-style:solid}.expand-button>span:first-child{font-size:19px;background:var(--green);width:29px;height:29px;display:grid;place-items:center;border-radius:3px}.expand-button b{font-size:10px;display:block;font-family:var(--mono);letter-spacing:.02em}.expand-button small{font-family:var(--mono);font-size:8px;color:#849080;display:block;margin-top:4px}.expand-button .arrow{margin-left:auto;font-size:16px}.sidebar-bottom{border-top:1px solid var(--line);margin-top:13px;padding-top:12px;display:flex;justify-content:space-between;color:#9aa39a;font-size:8px}.tiny-spark{color:#82a84e;letter-spacing:-2px}.main-panel{min-height:525px;padding:0 20px 19px}.outlet-header{height:84px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.outlet-heading{display:flex;gap:12px;align-items:center}.outlet-id{font-size:11px;color:#597644;background:#eaf2d8;padding:8px 7px;border-radius:3px}.outlet-heading .eyebrow{font-size:9px;margin:0 0 4px}.outlet-heading h2{font-size:20px;margin:0;letter-spacing:-.5px}.status-pill{font-size:9px;color:#668641;border:1px solid #d3e2be;padding:6px 9px;border-radius:20px}.status-pill .live-dot{width:6px;height:6px;margin-right:5px}.tabs{height:43px;display:flex;gap:24px;border-bottom:1px solid var(--line)}.tab{position:relative;border:0;background:none;color:#89928b;font-size:9px;padding:0;cursor:pointer}.tab:hover{color:var(--ink)}.tab.active{color:var(--ink);font-weight:500}.tab.active:after{content:'';position:absolute;bottom:-1px;left:0;right:0;height:2px;background:#83aa48}.tab-view{padding-top:16px}.hidden{display:none!important}.strategy-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.control-card{border:1px solid #e1e4dc;border-radius:4px;padding:13px 14px;background:#fdfcf8;min-height:137px}.card-head{display:flex;gap:9px;align-items:flex-start;margin-bottom:11px}.number{font-size:9px;color:#7c9f49;background:#edf3df;padding:5px 6px;border-radius:2px}.card-head h3{margin:0;font-size:13px;letter-spacing:-.2px}.card-head p{margin:3px 0 0;font-size:10px;color:#8a948b}.choice-list{display:flex;flex-direction:column;gap:5px}.brand-choice{display:flex;align-items:center;gap:8px;padding:7px 8px;border:1px solid #e5e8e0;border-radius:3px;cursor:pointer;background:#fff;transition:.15s}.brand-choice:hover{border-color:#b4c992}.brand-choice.selected{border-color:#92b45e;background:#f3f8e9;box-shadow:inset 3px 0 #8eaf55}.brand-choice input{accent-color:#74983f;margin:0}.brand-choice .brand-emoji{font-size:14px;width:19px;text-align:center}.brand-choice b{font-size:10px;display:block}.brand-choice small{font-size:9px;color:#859087;display:block;margin-top:1px}.brand-effect{margin-left:auto;text-align:right;font-family:var(--mono);font-size:8px;color:#719144}.hours-card{min-height:137px}.select-label{display:block;font-size:8px;color:#7e8a80;margin:12px 0 5px}.hours-card select{width:100%;height:31px;border:1px solid #dce1d7;background:#fff;border-radius:3px;padding:0 9px;font-family:var(--mono);font-size:10px;color:#28352e;outline-color:#99ba68}.hours-note{font-size:9px;color:#829087;margin-top:7px;line-height:1.4}.quality-card{grid-column:1 / -1;min-height:87px}.quality-card .card-head{margin-bottom:10px}.quality-row{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e7e9e3;padding-top:9px}.quality-row>div:first-child b{font-size:10px;display:block}.quality-row small{color:#889289;font-size:9px;display:block;margin-top:3px}.quality-control{display:flex;align-items:center;gap:9px}.quality-control button{border:0;background:var(--ink);color:#eef2e8;font-size:8px;padding:7px 10px;border-radius:2px;cursor:pointer}.quality-control button:hover:not(:disabled){background:#3a5140}.quality-control button:disabled{opacity:.42;cursor:not-allowed}.quality-control button span{color:var(--green);margin-left:5px}.tier-level{font-size:8px;color:#8a9488;white-space:nowrap}.quality-bars{display:none}.campaign-strip{display:flex;align-items:center;gap:11px;margin-top:12px;padding:11px;background:#edf3e2;border:1px solid #dce8ca;border-radius:4px}.campaign-icon{width:29px;height:29px;background:#d9ecb7;color:#537b30;display:grid;place-items:center;border-radius:3px;font-size:18px}.campaign-strip>div:nth-child(2){flex:1}.campaign-strip>div:nth-child(2)>b{font-size:8px;color:#6b854e}.campaign-strip p{margin:3px 0 0;font-size:10px;color:#4f5f4c}.run-button{background:var(--ink);color:#f8f8ee;border:0;border-radius:3px;padding:11px 13px;font-size:9px;cursor:pointer;white-space:nowrap;transition:.15s}.run-button:hover{background:#3d5642;transform:translateY(-1px)}.run-button span{color:var(--green);margin-left:8px;font-size:13px}.network-top,.ledger-head{display:flex;align-items:flex-end;justify-content:space-between;padding:1px 0 15px}.network-top h3,.ledger-head h3{font-size:15px;letter-spacing:-.4px;margin:0}.network-legend{display:flex;gap:13px;font-size:8px;color:#7e8980}.network-legend i{display:inline-block;width:7px;height:7px;margin-right:4px;border-radius:50%;background:#82aa49}.network-legend .legend-excitement{background:#f08b5e}.audience-list{display:grid;gap:8px}.audience-row{display:grid;grid-template-columns:minmax(125px,1.15fr) 2fr 95px;align-items:center;gap:12px;background:#fff;border:1px solid #e5e8e0;border-radius:3px;padding:10px 12px}.segment-name{display:flex;gap:8px;align-items:center}.segment-icon{font-size:17px}.segment-name b{display:block;font-size:11px}.segment-name small{display:block;font-size:8px;color:#929b92;margin-top:2px}.segment-bars{display:grid;gap:6px}.bar-line{display:grid;grid-template-columns:65px 1fr;align-items:center;gap:8px;font-family:var(--mono);font-size:8px;color:#829087}.bar-track{height:6px;background:#edf0e9;border-radius:5px;overflow:hidden}.bar-fill{height:100%;width:0;border-radius:5px;background:#8eb653;transition:width .35s}.bar-fill.excitement{background:#f18a5c}.audience-score{text-align:right;font-size:9px;color:#5a734b}.audience-score strong{font-size:14px;display:block;color:#33442f}.network-foot{display:flex;justify-content:space-between;margin-top:14px;padding-top:10px;border-top:1px solid var(--line);font-size:8px;color:#99a198}.ledger-head{align-items:center}.ledger-total{font-size:10px;color:#688d3e;background:#edf4e0;padding:7px 9px;border-radius:3px}.ledger-list{border-top:1px solid var(--line)}.ledger-row{display:grid;grid-template-columns:60px 1fr 100px 100px;align-items:center;gap:12px;padding:11px 8px;border-bottom:1px solid #e9ebe5;font-size:9px;color:#66736a}.ledger-row.header{font-size:8px;color:#9aa39c;background:#f7f7f1}.ledger-row .positive{color:#5d8c3d}.ledger-row .negative{color:#cc7959}.ledger-row b{font-weight:500;color:#3e4d43}footer{display:flex;justify-content:space-between;padding:17px 2px 22px;color:#8b958c;font-size:8px}footer b{color:#8eae56;font-size:12px;padding-left:4px}kbd{font:inherit;border:1px solid #bfc6b9;border-radius:2px;padding:1px 4px}.toast{position:fixed;left:50%;bottom:26px;transform:translate(-50%,20px);padding:11px 16px;background:var(--ink);color:#f6f6eb;border-radius:4px;box-shadow:0 5px 20px #0003;font:10px var(--mono);opacity:0;pointer-events:none;transition:.2s;z-index:5}.toast.show{opacity:1;transform:translate(-50%,0)}.modal{position:fixed;inset:0;background:#18211dd9;display:grid;place-items:center;padding:20px;z-index:10}.modal-card{position:relative;width:min(520px,100%);background:var(--panel);padding:30px;border-radius:5px;border:1px solid #cbd4c3;box-shadow:0 8px 0 #0e1512}.modal-card h2{font-size:25px;letter-spacing:-1px;margin:0 0 10px}.modal-card>p:not(.eyebrow){font-size:12px;line-height:1.65;color:#667168}.modal-close{position:absolute;right:15px;top:11px;border:0;background:none;font-size:24px;color:#738078;cursor:pointer}.guide-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px 18px;margin:23px 0}.guide-grid b{font-size:9px;color:#668641}.guide-grid span{display:block;font-size:10px;line-height:1.5;color:#78837a;margin-top:5px}.modal-done{width:100%;text-align:left}.modal-done span{float:right}.result-card{text-align:center}.result-card .eyebrow{margin-bottom:10px}.result-card h2{font-size:31px}.result-card .modal-done{margin-top:18px;text-align:center}
@media(max-width:850px){.shell{padding:0 22px}.workspace{grid-template-columns:220px minmax(0,1fr)}.main-panel{padding-left:15px;padding-right:15px}.strategy-grid{grid-template-columns:1fr}.quality-card{grid-column:auto}.sidebar{min-height:0}.quality-row{align-items:flex-start;gap:8px}.campaign-strip{flex-wrap:wrap}.campaign-strip .run-button{margin-left:auto}}
@media(max-width:620px){.shell{padding:0 13px}.topbar{height:58px}.top-status{font-size:0}.top-status .live-dot{margin:0}.top-status .divider{display:none}.game-heading{padding:24px 0 19px}.game-heading h1{font-size:40px}.heading-note{margin:0}.heading-note p{font-size:11px}.note-mark{width:32px;height:32px;font-size:18px}.hud{grid-template-columns:1fr 1fr;row-gap:15px;padding:13px 14px}.hud-stat{min-height:47px}.hud-stat:nth-child(3){padding-left:0;border-left:0}.hud-stat strong{font-size:19px}.workspace{grid-template-columns:1fr;gap:10px}.sidebar{padding:12px}.panel-title{padding-bottom:8px}.outlet-list{display:flex;overflow:auto;gap:5px;padding:6px 0}.outlet-item{min-width:145px;margin:0;padding:8px}.expand-button{margin-top:5px}.sidebar-bottom{display:none}.main-panel{padding:0 12px 13px;min-height:0}.outlet-header{height:70px}.outlet-heading h2{font-size:17px}.tabs{gap:16px;height:40px;overflow:auto}.tab{font-size:8px;white-space:nowrap}.tab-view{padding-top:12px}.control-card{padding:11px}.campaign-strip{gap:8px}.campaign-strip p{font-size:9px}.campaign-strip .run-button{width:100%;margin:2px 0 0}.audience-row{grid-template-columns:1fr auto;gap:7px;padding:9px}.segment-bars{grid-column:1/-1;grid-row:2}.audience-score{grid-column:2;grid-row:1}.network-top{align-items:flex-start;gap:7px;flex-direction:column}.network-top h3{font-size:13px}.network-foot{font-size:7px;gap:10px}.ledger-row{grid-template-columns:40px 1fr 70px 65px;gap:6px;font-size:8px;padding:10px 4px}.ledger-row.header{font-size:7px}.guide-grid{grid-template-columns:1fr;gap:12px}.modal-card{padding:24px 20px}.modal-card h2{font-size:22px}footer{font-size:7px;gap:8px}footer span:nth-child(2){display:none}}

(() => {
  const segments = [
    { id: 'commuters', name: '5AM Commuters', icon: '☼', note: 'Up before the sun', interest: 31, excitement: 22 },
    { id: 'families', name: 'Family Wagons', icon: '⌂', note: 'Clean car, happy kids', interest: 38, excitement: 26 },
    { id: 'enthusiasts', name: 'Car Enthusiasts', icon: '✦', note: 'Every detail matters', interest: 22, excitement: 28 },
    { id: 'dealhunters', name: 'Deal Hunters', icon: '＄', note: 'Value is the vibe', interest: 34, excitement: 20 },
    { id: 'nightowls', name: 'Night Owls', icon: '☾', note: 'Late shift, late wash', interest: 18, excitement: 19 }
  ];
  const brands = [
    { id: 'neighborhood', name: 'Bubble Base', icon: '🫧', desc: 'Friendly neighborhood clean.', effect: 'ALL-ROUNDER', lift: [1, 2, 1, 1, 0], color: '#b5db72' },
    { id: 'dawn', name: 'Dawn Patrol', icon: '☀️', desc: 'Fresh cars before first light.', effect: 'COMMUTER MAGNET', lift: [11, -1, 0, 0, -2], color: '#f5bc67' },
    { id: 'showtime', name: 'Foam & Fame', icon: '✨', desc: 'Big lights. Bigger suds. Showtime.', effect: 'BUZZ BUILDER', lift: [0, 2, 8, 0, 5], color: '#ea9bbc' },
    { id: 'value', name: 'The Clean Machine', icon: '⚙️', desc: 'No frills. No surprises. Good value.', effect: 'BUDGET FAVORITE', lift: [0, 1, -2, 10, 0], color: '#8ebeff' }
  ];
  const hours = [
    { value: 5, label: '5:00 AM', customers: 1.24, wage: 210, bonus: 12, note: 'Early opening catches the commuter rush. A longer shift means higher staffing costs.' },
    { value: 7, label: '7:00 AM', customers: 1.08, wage: 155, bonus: 6, note: 'A little head start for the morning crowd, with a manageable staff bill.' },
    { value: 9, label: '9:00 AM', customers: .94, wage: 115, bonus: 0, note: 'A sensible start. You will miss some early commuters, but save on staffing.' },
    { value: 11, label: '11:00 AM', customers: .78, wage: 85, bonus: -4, note: 'Keep payroll low and focus on midday customers.' }
  ];
  const locations = [
    { name: 'RIVERFRONT', cost: 8000, factor: 1.15 },
    { name: 'MILL DISTRICT', cost: 10500, factor: 1.05 },
    { name: 'OAK HOLLOW', cost: 12000, factor: .96 },
    { name: 'AIRPORT ROW', cost: 15000, factor: 1.2 },
    { name: 'SUNSET PLAZA', cost: 18000, factor: 1.1 }
  ];
  const state = {
    day: 1, cash: 12500, buzz: 24, selected: 0, ended: false, lastNet: 0,
    outlets: [{ name: 'BUBBLE BASE', location: 'DOWNTOWN', brand: 'neighborhood', hour: 7, tier: 1, factor: 1, audiences: segments.map(s => ({ interest: s.interest, excitement: s.excitement })), totalCustomers: 0 }],
    ledger: [],
    dailyWeather: ['Clear skies', 'Cloudy, but dry', 'A little drizzle', 'Perfect wash weather', 'Windy on the avenue', 'Blue-sky special', 'Passing showers']
  };
  const $ = id => document.getElementById(id);
  let toastTimer;
  const selectedOutlet = () => state.outlets[state.selected];
  const currentBrand = outlet => brands.find(b => b.id === outlet.brand);
  const currentHours = outlet => hours.find(h => h.value === Number(outlet.hour));
  const money = n => '$' + Math.round(n).toLocaleString('en-US');
  const clamp = n => Math.max(0, Math.min(100, Math.round(n)));
  const pad = n => String(n).padStart(2, '0');

  function showToast(message) {
    const toast = $('toast'); toast.textContent = message; toast.classList.add('show');
    clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('show'), 2200);
  }
  function updateHud() {
    $('dayStat').innerHTML = `${pad(Math.min(state.day, 30))}<span class="stat-dim"> / 30</span>`;
    $('cashStat').textContent = money(state.cash);
    $('cashDelta').textContent = state.ledger.length ? `${state.lastNet >= 0 ? '+' : '−'}${money(Math.abs(state.lastNet))} LAST DAY` : 'READY TO ROLL';
    $('cashDelta').style.color = state.lastNet < 0 ? '#f09a72' : '';
    $('buzzStat').innerHTML = `${state.buzz}<span class="stat-dim"> / 100</span>`;
    $('buzzMeter').style.width = `${state.buzz}%`;
    $('dayProgress').style.width = `${Math.min(100, (state.day - 1) / 30 * 100)}%`;
    $('washCount').textContent = pad(state.outlets.length);
    $('expandBtn').disabled = state.outlets.length >= 6 || state.cash < 8000;
    $('expandBtn').style.opacity = $('expandBtn').disabled ? '.52' : '1';
  }
  function renderOutlets() {
    $('outletList').innerHTML = state.outlets.map((o, i) => `<div class="outlet-item ${i === state.selected ? 'active' : ''}" data-outlet="${i}"><div class="outlet-item-left"><span class="outlet-icon">${i === 0 ? '▤' : '▥'}</span><div><b>${o.name}</b><small>${o.location} · TIER ${o.tier}</small></div></div><span class="outlet-cash">${money(o.totalCustomers)}<small style="display:block;font-size:7px;color:#99a198;text-align:right">CARS</small></span></div>`).join('');
    document.querySelectorAll('.outlet-item').forEach(el => el.addEventListener('click', () => { state.selected = Number(el.dataset.outlet); render(); }));
    $('expandBtn').disabled = state.outlets.length >= 6 || state.cash < 8000;
    $('expandBtn').style.opacity = $('expandBtn').disabled ? '.52' : '1';
  }
  function renderStrategy() {
    const o = selectedOutlet();
    $('outletId').textContent = pad(state.selected + 1);
    $('outletName').textContent = o.name;
    $('outletLocation').textContent = `${o.location} • ${state.day === 1 ? 'EST. TODAY' : `OPERATING ${state.day - 1} DAYS`}`;
    $('brandChoices').innerHTML = brands.map(b => `<label class="brand-choice ${o.brand === b.id ? 'selected' : ''}"><input type="radio" name="brand" value="${b.id}" ${o.brand === b.id ? 'checked' : ''}><span class="brand-emoji">${b.icon}</span><span><b>${b.name}</b><small>${b.desc}</small></span><span class="brand-effect">${b.effect}</span></label>`).join('');
    document.querySelectorAll('input[name="brand"]').forEach(input => input.addEventListener('change', () => { o.brand = input.value; render(); }));
    $('hoursSelect').innerHTML = hours.map(h => `<option value="${h.value}" ${Number(o.hour) === h.value ? 'selected' : ''}>${h.label}${h.value === 5 ? '  ·  EARLY BIRD' : ''}</option>`).join('');
    $('hoursSelect').onchange = e => { o.hour = Number(e.target.value); render(); };
    $('hoursNote').textContent = currentHours(o).note;
    const cost = [0, 2400, 4700][o.tier - 1];
    $('tierLevel').textContent = `TIER ${o.tier} / 3`;
